def topological_order(graph):
    result, visiting, visited = [], set(), set()
    def visit(node):
        if node in visiting:
            raise ValueError("cycle")
        if node in visited:
            return
        visiting.add(node)
        for dependency in graph.get(node, []):
            visit(dependency)
        visiting.remove(node)
        visited.add(node)
        result.append(node)
    for node in graph:
        visit(node)
    return result
